ds = unwrap(u:eval_load_jsonl("fixtures/math/five_problems.jsonl", {}))
print("oracle run:")
r = unwrap(u:eval_run(ds, :u:oracle, {out_path: "out/eval_smoke.jsonl", build: "test", decoding: "stub"}))
u:eval_report(r)
